    INSERT INTO activities (lesson_id,activity_type,sort_order,turn_id,word_id,prompt,instruction,difficulty,config,metadata) VALUES (v_l_2,'speak',17,NULL,NULL,'کارمند مدرک شناسایی می‌خواهد؛ آن را روی میز می‌گذاری و معرفی می‌کنی.','در موقعیت تازه، پاسخ مناسب را با صدای خودت بگو.',1,CAST('{"mode":"scenario_transfer","scenarioFa":"کارمند مدرک شناسایی می‌خواهد؛ آن را روی میز می‌گذاری و معرفی می‌کنی.","scenario_fa":"کارمند مدرک شناسایی می‌خواهد؛ آن را روی میز می‌گذاری و معرفی می‌کنی.","accepted":["Hier ist mein Ausweis.","Das ist mein Ausweis."],"acceptedIntents":["Hier ist mein Ausweis.","Das ist mein Ausweis."],"accepted_intents":["Hier ist mein Ausweis.","Das ist mein Ausweis."],"input":"speech","audioRequired":false,"textVisible":false,"scored":true,"independent":true,"masteryCheck":false,"cumulativeMastery":false}' AS JSON),JSON_OBJECT('contractMode','scenario_transfer','typing',FALSE,'series',9));
