    INSERT INTO activities (lesson_id,activity_type,sort_order,turn_id,word_id,prompt,instruction,difficulty,config,metadata) VALUES (v_l_3,'reading_comprehension',8,NULL,NULL,'کدام توضیح با الگوی این گفت‌وگو هماهنگ است؟','توضیح کوتاه را بخوان و گزینهٔ درست را لمس کن.',1,CAST('{"mode":"micro_grammar","input":"tap_choice","scored":false,"explanationFa":"برای کاری که از گذشته آغاز شده و هنوز ادامه دارد، از «seit» و زمان حال استفاده می‌کنیم: «Ich wohne seit einem Monat hier.»","explanation_fa":"برای کاری که از گذشته آغاز شده و هنوز ادامه دارد، از «seit» و زمان حال استفاده می‌کنیم: «Ich wohne seit einem Monat hier.»","optionsFa":["مدت زمان با seit","شناخت معنای واژه‌ها بدون ساختن جمله","تمرین آهنگ و تلفظ یک واژه"],"options_fa":["مدت زمان با seit","شناخت معنای واژه‌ها بدون ساختن جمله","تمرین آهنگ و تلفظ یک واژه"],"answerIndex":0,"answer_index":0}' AS JSON),JSON_OBJECT('contractMode','micro_grammar','typing',FALSE,'series',9,'phase','explicit_teaching'));
