    INSERT INTO activities (lesson_id,activity_type,sort_order,turn_id,word_id,prompt,instruction,difficulty,config,metadata) VALUES (v_l_3,'speak',17,NULL,NULL,'کارمند تاریخ تولدت را نشنیده؛ آن را دوباره با یک جملهٔ کامل بگو.','در موقعیت تازه، پاسخ مناسب را با صدای خودت بگو.',1,CAST('{"mode":"scenario_transfer","scenarioFa":"کارمند تاریخ تولدت را نشنیده؛ آن را دوباره با یک جملهٔ کامل بگو.","scenario_fa":"کارمند تاریخ تولدت را نشنیده؛ آن را دوباره با یک جملهٔ کامل بگو.","accepted":["Mein Geburtsdatum ist der zwölfte Mai.","Ich bin am zwölften Mai geboren."],"acceptedIntents":["Mein Geburtsdatum ist der zwölfte Mai.","Ich bin am zwölften Mai geboren."],"accepted_intents":["Mein Geburtsdatum ist der zwölfte Mai.","Ich bin am zwölften Mai geboren."],"input":"speech","audioRequired":false,"textVisible":false,"scored":true,"independent":true,"masteryCheck":false,"cumulativeMastery":false}' AS JSON),JSON_OBJECT('contractMode','scenario_transfer','typing',FALSE,'series',9));
    INSERT INTO activities (lesson_id,activity_type,sort_order,turn_id,word_id,prompt,instruction,difficulty,config,metadata) VALUES (v_l_3,'speak',18,NULL,NULL,'همسایهٔ تازه‌ات می‌پرسد چند وقت است در برلین هستی.','در موقعیت تازه، پاسخ مناسب را با صدای خودت بگو.',1,CAST('{"mode":"scenario_transfer","scenarioFa":"همسایهٔ تازه‌ات می‌پرسد چند وقت است در برلین هستی.","scenario_fa":"همسایهٔ تازه‌ات می‌پرسد چند وقت است در برلین هستی.","accepted":["Ich wohne seit einem Monat in Berlin.","Seit einem Monat bin ich hier."],"acceptedIntents":["Ich wohne seit einem Monat in Berlin.","Seit einem Monat bin ich hier."],"accepted_intents":["Ich wohne seit einem Monat in Berlin.","Seit einem Monat bin ich hier."],"input":"speech","audioRequired":false,"textVisible":false,"scored":true,"independent":true,"masteryCheck":false,"cumulativeMastery":false}' AS JSON),JSON_OBJECT('contractMode','scenario_transfer','typing',FALSE,'series',9));
